import json
import re
from collections import deque
from typing import Dict, List, Tuple


_HEADER_RE = re.compile(r"^\[(.+)\]\s*$")
_CHOICE_RE = re.compile(r"^(\d+)\.\s+(.*)$")


def _split_arrow(text: str) -> Tuple[str, str]:
    if "->" in text:
        left, right = text.rsplit("->", 1)
        return left.strip(), right.strip()
    return text.strip(), ""


def _parse_line(text: str) -> Tuple[str, str, str]:
    left, target = _split_arrow(text)
    if ":" in left:
        speaker, line_text = left.split(":", 1)
        return speaker.strip(), line_text.strip(), target
    return "", left.strip(), target


def parse_script(text: str) -> Dict[str, List[Dict[str, str]]]:
    lines = text.splitlines()
    sections: List[Tuple[str, List[str]]] = []
    node_order: List[str] = []

    current_id = None
    current_lines: List[str] = []

    for raw in lines:
        line = raw.strip()
        if not line:
            continue
        header_match = _HEADER_RE.match(line)
        if header_match:
            if current_id is not None:
                sections.append((current_id, current_lines))
            current_id = header_match.group(1).strip()
            current_lines = []
            if current_id not in node_order:
                node_order.append(current_id)
            continue
        if current_id is None:
            # Ignore text before the first header
            continue
        current_lines.append(line)

    if current_id is not None:
        sections.append((current_id, current_lines))

    nodes: List[Dict[str, str]] = []
    edges: List[Dict[str, str]] = []
    node_map: Dict[str, Dict[str, str]] = {}

    for node_id, content_lines in sections:
        if node_id in node_map:
            continue
        has_choice = any(_CHOICE_RE.match(l) for l in content_lines)
        if has_choice:
            node = {"id": node_id, "text": "", "speaker": "", "type": "choice"}
            for line in content_lines:
                cm = _CHOICE_RE.match(line)
                if not cm:
                    continue
                choice_body = cm.group(2)
                choice_text, target = _split_arrow(choice_body)
                if target:
                    edges.append({"from": node_id, "to": target, "text": choice_text})
            nodes.append(node)
            node_map[node_id] = node
            continue

        # Line node
        speaker = ""
        text_content = ""
        target = ""
        if content_lines:
            speaker, text_content, target = _parse_line(content_lines[0])
        node = {"id": node_id, "text": text_content, "speaker": speaker, "type": "line"}
        nodes.append(node)
        node_map[node_id] = node
        if target:
            edges.append({"from": node_id, "to": target, "text": ""})

        # If additional lines contain arrows, treat them as extra outgoing edges.
        for extra in content_lines[1:]:
            _, _, extra_target = _parse_line(extra)
            if extra_target:
                edges.append({"from": node_id, "to": extra_target, "text": ""})

    # Create stub nodes for missing targets
    for edge in edges:
        target_id = edge["to"]
        if target_id and target_id not in node_map:
            stub = {"id": target_id, "text": "", "speaker": "", "type": "line"}
            nodes.append(stub)
            node_map[target_id] = stub

    if not nodes:
        return {"nodes": [], "edges": []}

    entry_id = nodes[0]["id"]

    # Reachability filter
    adj: Dict[str, List[str]] = {}
    for edge in edges:
        adj.setdefault(edge["from"], []).append(edge["to"])

    reachable = set([entry_id])
    queue = deque([entry_id])
    while queue:
        cur = queue.popleft()
        for nxt in adj.get(cur, []):
            if nxt not in reachable:
                reachable.add(nxt)
                queue.append(nxt)

    nodes = [n for n in nodes if n["id"] in reachable]
    edges = [e for e in edges if e["from"] in reachable and e["to"] in reachable]

    return {"nodes": nodes, "edges": edges}


def _dot_escape(value: str) -> str:
    return value.replace("\\", "\\\\").replace("\"", "\\\"")


def graph_to_dot(graph: Dict[str, List[Dict[str, str]]]) -> str:
    lines = [
        "digraph Dialogue {",
        "  rankdir=LR;",
        "  node [shape=box, fontname=\"Helvetica\"];",
    ]

    for node in graph.get("nodes", []):
        node_id = _dot_escape(node["id"])
        label = _dot_escape(node["id"])
        lines.append(f'  "{node_id}" [label="{label}"];')

    for edge in graph.get("edges", []):
        src = _dot_escape(edge["from"])
        dst = _dot_escape(edge["to"])
        label = _dot_escape(edge.get("text", ""))
        if label:
            lines.append(f'  "{src}" -> "{dst}" [label="{label}"];')
        else:
            lines.append(f'  "{src}" -> "{dst}";')

    lines.append("}")
    return "\n".join(lines)


def main() -> None:
    with open("/app/script.txt", "r", encoding="utf-8") as f:
        script_text = f.read()

    graph = parse_script(script_text)

    with open("/app/dialogue.json", "w", encoding="utf-8") as f:
        json.dump(graph, f, indent=2)

    with open("/app/dialogue.dot", "w", encoding="utf-8") as f:
        f.write(graph_to_dot(graph))


if __name__ == "__main__":
    main()
EOF"}
